You are a smart contract auditor, identify and explain severe vulnerabilities in the provided smart contract. Make sure that they are exploitable in real world and beneficial to attackers. Provide each identified vulnerability with intermediate reasoning and its associated function. Remember, you must provide the entire function code and do not use "...". Make your reasoning comprehensive and detailed. 
You should only output in below json format:
{
    "output_list": [
        {
            "function_name": "<function_name_1>",
            "code": "<original_function_code_1>",
            "vulnerability": "<short_vulnera_desc_1>",
            "reason": "<reason_1>"
        },
        {
            "function_name": "<function_name_2>",
            "code": "<original_function_code_2>",
            "vulnerability": "<short_vulnera_desc_2>",
            "reason": "<reason_2>"
        }
    ]
}
Output 3 most severe vulnerabilities.
If no vulnerability is detected, you should only output in this json format {"output_list": []}.
Smart contract code:

pragma experimental ABIEncoderV2; pragma solidity ^0.6.12; interface IERC20 { function totalSupply() external view returns (uint256); function balanceOf(address account) external view returns (uint256); function transfer(address recipient, uint256 amount) external returns (bool); function allowance(address owner, address spender) external view returns (uint256); function approve(address spender, uint256 amount) external returns (bool); function transferFrom(address sender, address recipient, uint256 amount) external returns (bool); event Transfer(address indexed from, address indexed to, uint256 value); event Approval(address indexed owner, address indexed spender, uint256 value); } library SafeMath { function add(uint256 a, uint256 b) internal pure returns (uint256) { uint256 c = a + b; require(c >= a, "SafeMath: addition overflow"); return c; } function sub(uint256 a, uint256 b) internal pure returns (uint256) { return sub(a, b, "SafeMath: subtraction overflow"); } function sub(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b <= a, errorMessage); uint256 c = a - b; return c; } function mul(uint256 a, uint256 b) internal pure returns (uint256) { if (a == 0) { return 0; } uint256 c = a * b; require(c / a == b, "SafeMath: multiplication overflow"); return c; } function div(uint256 a, uint256 b) internal pure returns (uint256) { return div(a, b, "SafeMath: division by zero"); } function div(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b > 0, errorMessage); uint256 c = a / b; return c; } function mod(uint256 a, uint256 b) internal pure returns (uint256) { return mod(a, b, "SafeMath: modulo by zero"); } function mod(uint256 a, uint256 b, string memory errorMessage) internal pure returns (uint256) { require(b != 0, errorMessage); return a % b; } } library Address { function isContract(address account) internal view returns (bool) { uint256 size; assembly { size := extcodesize(account) } return size > 0; } function sendValue(address payable recipient, uint256 amount) internal { require(address(this).balance >= amount, "Address: insufficient balance"); (bool success, ) = recipient.call{ value: amount }(""); require(success, "Address: unable to send value, recipient may have reverted"); } function functionCall(address target, bytes memory data) internal returns (bytes memory) { return functionCall(target, data, "Address: low-level call failed"); } function functionCall(address target, bytes memory data, string memory errorMessage) internal returns (bytes memory) { return functionCallWithValue(target, data, 0, errorMessage); } function functionCallWithValue(address target, bytes memory data, uint256 value) internal returns (bytes memory) { return functionCallWithValue(target, data, value, "Address: low-level call with value failed"); } function functionCallWithValue(address target, bytes memory data, uint256 value, string memory errorMessage) internal returns (bytes memory) { require(address(this).balance >= value, "Address: insufficient balance for call"); require(isContract(target), "Address: call to non-contract"); (bool success, bytes memory returndata) = target.call{ value: value }(data); return _verifyCallResult(success, returndata, errorMessage); } function functionStaticCall(address target, bytes memory data) internal view returns (bytes memory) { return functionStaticCall(target, data, "Address: low-level static call failed"); } function functionStaticCall(address target, bytes memory data, string memory errorMessage) internal view returns (bytes memory) { require(isContract(target), "Address: static call to non-contract"); (bool success, bytes memory returndata) = target.staticcall(data); return _verifyCallResult(success, returndata, errorMessage); } function _verifyCallResult(bool success, bytes memory returndata, string memory errorMessage) private pure returns(bytes memory) { if (success) { return returndata; } else { if (returndata.length > 0) { assembly { let returndata_size := mload(returndata) revert(add(32, returndata), returndata_size) } } else { revert(errorMessage); } } } } library SafeERC20 { using SafeMath for uint256; using Address for address; function safeTransfer(IERC20 token, address to, uint256 value) internal { _callOptionalReturn(token, abi.encodeWithSelector(token.transfer.selector, to, value)); } function safeTransferFrom(IERC20 token, address from, address to, uint256 value) internal { _callOptionalReturn(token, abi.encodeWithSelector(token.transferFrom.selector, from, to, value)); } function safeApprove(IERC20 token, address spender, uint256 value) internal { require((value == 0) || (token.allowance(address(this), spender) == 0), "SafeERC20: approve from non-zero to non-zero allowance" ); _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, value)); } function safeIncreaseAllowance(IERC20 token, address spender, uint256 value) internal { uint256 newAllowance = token.allowance(address(this), spender).add(value); _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, newAllowance)); } function safeDecreaseAllowance(IERC20 token, address spender, uint256 value) internal { uint256 newAllowance = token.allowance(address(this), spender).sub(value, "SafeERC20: decreased allowance below zero"); _callOptionalReturn(token, abi.encodeWithSelector(token.approve.selector, spender, newAllowance)); } function _callOptionalReturn(IERC20 token, bytes memory data) private { bytes memory returndata = address(token).functionCall(data, "SafeERC20: low-level call failed"); if (returndata.length > 0) { require(abi.decode(returndata, (bool)), "SafeERC20: ERC20 operation did not succeed"); } } } abstract contract Context { function _msgSender() internal view virtual returns (address payable) { return msg.sender; } function _msgData() internal view virtual returns (bytes memory) { this; return msg.data; } } abstract contract Ownable is Context { address private _owner; event OwnershipTransferred(address indexed previousOwner, address indexed newOwner); constructor () internal { address msgSender = _msgSender(); _owner = msgSender; emit OwnershipTransferred(address(0), msgSender); } function owner() public view returns (address) { return _owner; } modifier onlyOwner() { require(_owner == _msgSender(), "Ownable: caller is not the owner"); _; } function renounceOwnership() public virtual onlyOwner { emit OwnershipTransferred(_owner, address(0)); _owner = address(0); } function transferOwnership(address newOwner) public virtual onlyOwner { require(newOwner != address(0), "Ownable: new owner is the zero address"); emit OwnershipTransferred(_owner, newOwner); _owner = newOwner; } } interface IController { function stablecoins() external view returns (address[3] memory); function vaults() external view returns (address[3] memory); function underlyingVaults(uint256 i) external view returns (address vault); function curveVault() external view returns (address); function pnl() external view returns (address); function insurance() external view returns (address); function lifeGuard() external view returns (address); function buoy() external view returns (address); function reward() external view returns (address); function isValidBigFish( bool pwrd, bool deposit, uint256 amount ) external view returns (bool); function withdrawHandler() external view returns (address); function emergencyHandler() external view returns (address); function depositHandler() external view returns (address); function totalAssets() external view returns (uint256); function gTokenTotalAssets() external view returns (uint256); function eoaOnly(address sender) external; function getSkimPercent() external view returns (uint256); function gToken(bool _pwrd) external view returns (address); function emergencyState() external view returns (bool); function deadCoin() external view returns (uint256); function distributeStrategyGainLoss(uint256 gain, uint256 loss) external; function burnGToken( bool pwrd, bool all, address account, uint256 amount, uint256 bonus ) external; function mintGToken( bool pwrd, address account, uint256 amount ) external; function getUserAssets(bool pwrd, address account) external view returns (uint256 deductUsd); function referrals(address account) external view returns (address); function addReferral(address account, address referral) external; function getStrategiesTargetRatio() external view returns (uint256[] memory); function withdrawalFee(bool pwrd) external view returns (uint256); function validGTokenDecrease(uint256 amount) external view returns (bool); } interface IPausable { function paused() external view returns (bool); } contract Controllable is Ownable { address public controller; event ChangeController(address indexed oldController, address indexed newController); modifier whenNotPaused() { require(!_pausable().paused(), "Pausable: paused"); _; } modifier whenPaused() { require(_pausable().paused(), "Pausable: not paused"); _; } function ctrlPaused() public view returns (bool) { return _pausable().paused(); } function setController(address newController) external onlyOwner { require(newController != address(0), "setController: !0x"); address oldController = controller; controller = newController; emit ChangeController(oldController, newController); } function _controller() internal view returns (IController) { require(controller != address(0), "Controller not set"); return IController(controller); } function _pausable() internal view returns (IPausable) { require(controller != address(0), "Controller not set"); return IPausable(controller); } } contract Constants { uint8 public constant N_COINS = 3; uint8 public constant DEFAULT_DECIMALS = 18; uint256 public constant DEFAULT_DECIMALS_FACTOR = uint256(10)**DEFAULT_DECIMALS; uint8 public constant CHAINLINK_PRICE_DECIMALS = 8; uint256 public constant CHAINLINK_PRICE_DECIMAL_FACTOR = uint256(10)**CHAINLINK_PRICE_DECIMALS; uint8 public constant PERCENTAGE_DECIMALS = 4; uint256 public constant PERCENTAGE_DECIMAL_FACTOR = uint256(10)**PERCENTAGE_DECIMALS; uint256 public constant CURVE_RATIO_DECIMALS = 6; uint256 public constant CURVE_RATIO_DECIMALS_FACTOR = uint256(10)**CURVE_RATIO_DECIMALS; } interface IToken { function factor() external view returns (uint256); function factor(uint256 totalAssets) external view returns (uint256); function mint( address account, uint256 _factor, uint256 amount ) external; function burn( address account, uint256 _factor, uint256 amount ) external; function burnAll(address account) external; function totalAssets() external view returns (uint256); function getPricePerShare() external view returns (uint256); function getShareAssets(uint256 shares) external view returns (uint256); function getAssets(address account) external view returns (uint256); } interface IVault { function withdraw(uint256 amount) external; function withdraw(uint256 amount, address recipient) external; function withdrawByStrategyOrder( uint256 amount, address recipient, bool reversed ) external; function withdrawByStrategyIndex( uint256 amount, address recipient, uint256 strategyIndex ) external; function deposit(uint256 amount) external; function updateStrategyRatio(uint256[] calldata strategyRetios) external; function totalAssets() external view returns (uint256); function getStrategiesLength() external view returns (uint256); function strategyHarvestTrigger(uint256 index, uint256 callCost) external view returns (bool); function strategyHarvest(uint256 index) external returns (bool); function getStrategyAssets(uint256 index) external view returns (uint256); function token() external view returns (address); function vault() external view returns (address); function investTrigger() external view returns (bool); function invest() external; } contract FixedStablecoins is Constants { address public immutable DAI; address public immutable USDC; address public immutable USDT; uint256 public immutable DAI_DECIMALS; uint256 public immutable USDC_DECIMALS; uint256 public immutable USDT_DECIMALS; constructor(address[N_COINS] memory _tokens, uint256[N_COINS] memory _decimals) public { DAI = _tokens[0]; USDC = _tokens[1]; USDT = _tokens[2]; DAI_DECIMALS = _decimals[0]; USDC_DECIMALS = _decimals[1]; USDT_DECIMALS = _decimals[2]; } function underlyingTokens() internal view returns (address[N_COINS] memory tokens) { tokens[0] = DAI; tokens[1] = USDC; tokens[2] = USDT; } function getToken(uint256 index) internal view returns (address) { if (index == 0) { return DAI; } else if (index == 1) { return USDC; } else { return USDT; } } function decimals() internal view returns (uint256[N_COINS] memory _decimals) { _decimals[0] = DAI_DECIMALS; _decimals[1] = USDC_DECIMALS; _decimals[2] = USDT_DECIMALS; } function getDecimal(uint256 index) internal view returns (uint256) { if (index == 0) { return DAI_DECIMALS; } else if (index == 1) { return USDC_DECIMALS; } else { return USDT_DECIMALS; } } } contract FixedGTokens { IToken public immutable pwrd; IToken public immutable gvt; constructor(address _pwrd, address _gvt) public { pwrd = IToken(_pwrd); gvt = IToken(_gvt); } function gTokens(bool _pwrd) internal view returns (IToken) { if (_pwrd) { return pwrd; } else { return gvt; } } } contract FixedVaults is Constants { address public immutable DAI_VAULT; address public immutable USDC_VAULT; address public immutable USDT_VAULT; constructor(address[N_COINS] memory _vaults) public { DAI_VAULT = _vaults[0]; USDC_VAULT = _vaults[1]; USDT_VAULT = _vaults[2]; } function getVault(uint256 index) internal view returns (address) { if (index == 0) { return DAI_VAULT; } else if (index == 1) { return USDC_VAULT; } else { return USDT_VAULT; } } function vaults() internal view returns (address[N_COINS] memory _vaults) { _vaults[0] = DAI_VAULT; _vaults[1] = USDC_VAULT; _vaults[2] = USDT_VAULT; } } contract Whitelist is Ownable { mapping(address => bool) public whitelist; event LogAddToWhitelist(address indexed user); event LogRemoveFromWhitelist(address indexed user); modifier onlyWhitelist() { require(whitelist[msg.sender], "only whitelist"); _; } function addToWhitelist(address user) external onlyOwner { require(user != address(0), "WhiteList: 0x"); whitelist[user] = true; emit LogAddToWhitelist(user); } function removeFromWhitelist(address user) external onlyOwner { require(user != address(0), "WhiteList: 0x"); whitelist[user] = false; emit LogRemoveFromWhitelist(user); } } abstract contract Pausable is Context { event Paused(address account); event Unpaused(address account); bool private _paused; constructor () internal { _paused = false; } function paused() public view returns (bool) { return _paused; } modifier whenNotPaused() { require(!_paused, "Pausable: paused"); _; } modifier whenPaused() { require(_paused, "Pausable: not paused"); _; } function _pause() internal virtual whenNotPaused { _paused = true; emit Paused(_msgSender()); } function _unpause() internal virtual whenPaused { _paused = false; emit Unpaused(_msgSender()); } } interface ICurve3Pool { function coins(uint256 i) external view returns (address); function get_virtual_price() external view returns (uint256); function get_dy( int128 i, int128 j, uint256 dx ) external view returns (uint256); function calc_withdraw_one_coin(uint256 _token_amount, int128 i) external view returns (uint256); function calc_token_amount(uint256[3] calldata inAmounts, bool deposit) external view returns (uint256); function balances(int128 i) external view returns (uint256); } interface ICurve3Deposit { function exchange( int128 i, int128 j, uint256 dx, uint256 min_dy ) external; function add_liquidity(uint256[3] calldata uamounts, uint256 min_mint_amount) external; function remove_liquidity(uint256 amount, uint256[3] calldata min_uamounts) external; function remove_liquidity_imbalance(uint256[3] calldata amounts, uint256 max_burn_amount) external; function remove_liquidity_one_coin( uint256 _token_amount, int128 i, uint256 min_uamount ) external; function get_dy( int128 i, int128 j, uint256 dx ) external view returns (uint256); } interface ICurveMetaPool { function coins(uint256 i) external view returns (address); function get_virtual_price() external view returns (uint256); function get_dy_underlying( int128 i, int128 j, uint256 dx ) external view returns (uint256); function calc_withdraw_one_coin(uint256 _token_amount, int128 i) external view returns (uint256); function calc_token_amount(uint256[2] calldata inAmounts, bool deposit) external view returns (uint256); function exchange( int128 i, int128 j, uint256 dx, uint256 min_dy ) external; function add_liquidity(uint256[2] calldata uamounts, uint256 min_mint_amount) external; function remove_liquidity_one_coin( uint256 _token_amount, int128 i, uint256 min_uamount ) external; } interface ICurveZap { function add_liquidity(uint256[4] calldata uamounts, uint256 min_mint_amount) external; function remove_liquidity(uint256 amount, uint256[4] calldata min_uamounts) external; function remove_liquidity_imbalance(uint256[4] calldata amounts, uint256 max_burn_amount) external; function remove_liquidity_one_coin( uint256 _token_amount, int128 i, uint256 min_uamount ) external; function calc_withdraw_one_coin(uint256 _token_amount, int128 i) external view returns (uint256); function calc_token_amount(uint256[4] calldata inAmounts, bool deposit) external view returns (uint256); function pool() external view returns (address); } interface AggregatorV3Interface { function decimals() external view returns (uint8); function description() external view returns (string memory); function version() external view returns (uint256); function getRoundData(uint80 _roundId) external view returns ( uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound ); function latestRoundData() external view returns ( uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound ); } interface IChainPrice { function getPriceFeed(uint256 i) external view returns (uint256 _price); } interface IBuoy { function safetyCheck() external view returns (bool); function updateRatios() external returns (bool); function updateRatiosWithTolerance(uint256 tolerance) external returns (bool); function lpToUsd(uint256 inAmount) external view returns (uint256); function usdToLp(uint256 inAmount) external view returns (uint256); function stableToUsd(uint256[3] calldata inAmount, bool deposit) external view returns (uint256); function stableToLp(uint256[3] calldata inAmount, bool deposit) external view returns (uint256); function singleStableFromLp(uint256 inAmount, int128 i) external view returns (uint256); function curvePool() external view returns (ICurve3Pool); function getVirtualPrice() external view returns (uint256); function singleStableFromUsd(uint256 inAmount, int128 i) external view returns (uint256); function singleStableToUsd(uint256 inAmount, uint256 i) external view returns (uint256); } interface IERC20Detailed { function name() external view returns (string memory); function symbol() external view returns (string memory); function decimals() external view returns (uint8); } interface IInsurance { function calculateDepositDeltasOnAllVaults() external view returns (uint256[3] memory); function rebalanceTrigger() external view returns (bool sysNeedRebalance); function rebalance() external; function calcSkim() external view returns (uint256); function rebalanceForWithdraw(uint256 withdrawUsd, bool pwrd) external returns (bool); function getDelta(uint256 withdrawUsd) external view returns (uint256[3] memory delta); function getVaultDeltaForDeposit(uint256 amount) external view returns ( uint256[3] memory, uint256[3] memory, uint256 ); function sortVaultsByDelta(bool bigFirst) external view returns (uint256[3] memory vaultIndexes); function getStrategiesTargetRatio(uint256 utilRatio) external view returns (uint256[] memory); function setUnderlyingTokenPercent(uint256 coinIndex, uint256 percent) external; } interface ILifeGuard { function assets(uint256 i) external view returns (uint256); function totalAssets() external view returns (uint256); function getAssets() external view returns (uint256[3] memory); function totalAssetsUsd() external view returns (uint256); function availableUsd() external view returns (uint256 dollar); function availableLP() external view returns (uint256); function depositStable(bool rebalance) external returns (uint256); function investToCurveVault() external; function distributeCurveVault(uint256 amount, uint256[3] memory delta) external returns (uint256[3] memory); function deposit() external returns (uint256 usdAmount); function withdrawSingleByLiquidity( uint256 i, uint256 minAmount, address recipient ) external returns (uint256 usdAmount, uint256 amount); function withdrawSingleByExchange( uint256 i, uint256 minAmount, address recipient ) external returns (uint256 usdAmount, uint256 amount); function invest(uint256 whaleDepositAmount, uint256[3] calldata delta) external returns (uint256 dollarAmount); function getBuoy() external view returns (address); function investSingle( uint256[3] calldata inAmounts, uint256 i, uint256 j ) external returns (uint256 dollarAmount); function investToCurveVaultTrigger() external view returns (bool _invest); } interface IPnL { function calcPnL() external view returns (uint256, uint256); function increaseGTokenLastAmount(bool pwrd, uint256 dollarAmount) external; function decreaseGTokenLastAmount( bool pwrd, uint256 dollarAmount, uint256 bonus ) external; function lastGvtAssets() external view returns (uint256); function lastPwrdAssets() external view returns (uint256); function utilisationRatio() external view returns (uint256); function emergencyPnL() external; function recover() external; function distributeStrategyGainLoss( uint256 gain, uint256 loss, address reward ) external; function distributePriceChange(uint256 currentTotalAssets) external; } contract Controller is Pausable, Ownable, Whitelist, FixedStablecoins, FixedGTokens, IController { using SafeERC20 for IERC20; using SafeMath for uint256; address public override curveVault; bool public preventSmartContracts = false; address public override insurance; address public override pnl; address public override lifeGuard; address public override buoy; address public override depositHandler; address public override withdrawHandler; address public override emergencyHandler; uint256 public override deadCoin = 99; bool public override emergencyState; uint256 public utilisationRatioLimitGvt; uint256 public utilisationRatioLimitPwrd; uint256 public bigFishThreshold = 100; uint256 public bigFishAbsoluteThreshold = 0; address public override reward; mapping(address => bool) public safeAddresses; mapping(uint256 => address) public override underlyingVaults; mapping(address => uint256) public vaultIndexes; mapping(address => address) public override referrals; mapping(bool => uint256) public override withdrawalFee; event LogNewWithdrawHandler(address tokens); event LogNewDepositHandler(address tokens); event LogNewVault(uint256 index, address vault); event LogNewCurveVault(address curveVault); event LogNewLifeguard(address lifeguard); event LogNewInsurance(address insurance); event LogNewPnl(address pnl); event LogNewBigFishThreshold(uint256 percent, uint256 absolute); event LogFlashSwitchUpdated(bool status); event LogNewSafeAddress(address account); event LogNewRewardsContract(address reward); event LogNewUtilLimit(bool indexed pwrd, uint256 limit); event LogNewCurveToStableDistribution(uint256 amount, uint256[N_COINS] amounts, uint256[N_COINS] delta); event LogNewWithdrawalFee(address user, bool pwrd, uint256 newFee); constructor( address pwrd, address gvt, address[N_COINS] memory _tokens, uint256[N_COINS] memory _decimals ) public FixedStablecoins(_tokens, _decimals) FixedGTokens(pwrd, gvt) {} function pause() external onlyWhitelist { _pause(); } function unpause() external onlyOwner { _unpause(); } function setWithdrawHandler(address _withdrawHandler, address _emergencyHandler) external onlyOwner { require(_withdrawHandler != address(0), "setWithdrawHandler: 0x"); withdrawHandler = _withdrawHandler; emergencyHandler = _emergencyHandler; emit LogNewWithdrawHandler(_withdrawHandler); } function setDepositHandler(address _depositHandler) external onlyOwner { require(_depositHandler != address(0), "setDepositHandler: 0x"); depositHandler = _depositHandler; emit LogNewDepositHandler(_depositHandler); } function stablecoins() external view override returns (address[N_COINS] memory) { return underlyingTokens(); } function getSkimPercent() external view override returns (uint256) { return IInsurance(insurance).calcSkim(); } function vaults() external view override returns (address[N_COINS] memory) { address[N_COINS] memory result; for (uint256 i = 0; i < N_COINS; i++) { result[i] = underlyingVaults[i]; } return result; } function setVault(uint256 index, address vault) external onlyOwner { require(vault != address(0), "setVault: 0x"); require(index < N_COINS, "setVault: !index"); underlyingVaults[index] = vault; vaultIndexes[vault] = index + 1; emit LogNewVault(index, vault); } function setCurveVault(address _curveVault) external onlyOwner { require(_curveVault != address(0), "setCurveVault: 0x"); curveVault = _curveVault; vaultIndexes[_curveVault] = N_COINS + 1; emit LogNewCurveVault(_curveVault); } function setLifeGuard(address _lifeGuard) external onlyOwner { require(_lifeGuard != address(0), "setLifeGuard: 0x"); lifeGuard = _lifeGuard; buoy = ILifeGuard(_lifeGuard).getBuoy(); emit LogNewLifeguard(_lifeGuard); } function setInsurance(address _insurance) external onlyOwner { require(_insurance != address(0), "setInsurance: 0x"); insurance = _insurance; emit LogNewInsurance(_insurance); } function setPnL(address _pnl) external onlyOwner { require(_pnl != address(0), "setPnl: 0x"); pnl = _pnl; emit LogNewPnl(_pnl); } function addSafeAddress(address account) external onlyOwner { safeAddresses[account] = true; emit LogNewSafeAddress(account); } function switchEoaOnly(bool check) external onlyOwner { preventSmartContracts = check; } function setBigFishThreshold(uint256 _percent, uint256 _absolute) external onlyOwner { require(_percent > 0, "_whaleLimit is 0"); bigFishThreshold = _percent; bigFishAbsoluteThreshold = _absolute; emit LogNewBigFishThreshold(_percent, _absolute); } function setReward(address _reward) external onlyOwner { require(_reward != address(0), "setReward: 0x"); reward = _reward; emit LogNewRewardsContract(_reward); } function addReferral(address account, address referral) external override { require(msg.sender == depositHandler, "!depositHandler"); if (account != address(0) && referral != address(0) && referrals[account] == address(0)) { referrals[account] = referral; } } function setWithdrawalFee(bool pwrd, uint256 newFee) external onlyOwner { withdrawalFee[pwrd] = newFee; emit LogNewWithdrawalFee(msg.sender, pwrd, newFee); } function totalAssets() external view override returns (uint256) { return emergencyState ? _totalAssetsEmergency() : _totalAssets(); } function gTokenTotalAssets() public view override returns (uint256) { (uint256 gvtAssets, uint256 pwrdAssets) = IPnL(pnl).calcPnL(); if (msg.sender == address(gvt)) { return gvtAssets; } if (msg.sender == address(pwrd)) { return pwrdAssets; } return 0; } function gToken(bool isPWRD) external view override returns (address) { return isPWRD ? address(pwrd) : address(gvt); } function isValidBigFish( bool pwrd, bool deposit, uint256 amount ) external view override returns (bool) { if (deposit && pwrd) { require(validGTokenIncrease(amount), "isBigFish: !validGTokenIncrease"); } else if (!pwrd && !deposit) { require(validGTokenDecrease(amount), "isBigFish: !validGTokenDecrease"); } (uint256 gvtAssets, uint256 pwrdAssets) = IPnL(pnl).calcPnL(); uint256 assets = pwrdAssets.add(gvtAssets); if (amount < bigFishAbsoluteThreshold) {