 return false; } else if (amount > assets) { return true; } else { return amount > assets.mul(bigFishThreshold).div(PERCENTAGE_DECIMAL_FACTOR); } } function distributeCurveAssets(uint256 amount, uint256[N_COINS] memory delta) external onlyWhitelist { uint256[N_COINS] memory amounts = ILifeGuard(lifeGuard).distributeCurveVault(amount, delta); emit LogNewCurveToStableDistribution(amount, amounts, delta); } function eoaOnly(address sender) public override { if (preventSmartContracts && !safeAddresses[tx.origin]) { require(sender == tx.origin, "EOA only"); } } function _totalAssets() private view returns (uint256) { require(IBuoy(buoy).safetyCheck(), "!buoy.safetyCheck"); uint256[N_COINS] memory lgAssets = ILifeGuard(lifeGuard).getAssets(); uint256[N_COINS] memory vaultAssets; for (uint256 i = 0; i < N_COINS; i++) { vaultAssets[i] = lgAssets[i].add(IVault(underlyingVaults[i]).totalAssets()); } uint256 totalLp = IVault(curveVault).totalAssets(); totalLp = totalLp.add(IBuoy(buoy).stableToLp(vaultAssets, true)); uint256 vp = IBuoy(buoy).getVirtualPrice(); return totalLp.mul(vp).div(DEFAULT_DECIMALS_FACTOR); } function _totalAssetsEmergency() private view returns (uint256) { IChainPrice chainPrice = IChainPrice(buoy); uint256 total; for (uint256 i = 0; i < N_COINS; i++) { if (i != deadCoin) { address tokenAddress = getToken(i); uint256 decimals = getDecimal(i); IERC20 token = IERC20(tokenAddress); uint256 price = chainPrice.getPriceFeed(i); uint256 assets = IVault(underlyingVaults[i]).totalAssets().add(token.balanceOf(lifeGuard)); assets = assets.mul(price).div(CHAINLINK_PRICE_DECIMAL_FACTOR); assets = assets.mul(DEFAULT_DECIMALS_FACTOR).div(decimals); total = total.add(assets); } } return total; } function emergency(uint256 coin) external onlyWhitelist { require(coin < N_COINS, "invalid coin"); if (!paused()) { _pause(); } deadCoin = coin; emergencyState = true; uint256 percent; for (uint256 i; i < N_COINS; i++) { if (i == coin) { percent = 10000; } else { percent = 0; } I