 amount); } function getUserAssets(bool pwrd, address account) external view override returns (uint256 deductUsd) { IToken gt = gTokens(pwrd); deductUsd = gt.getAssets(account); require(deductUsd > 0, "!minAmount"); } function validGTokenIncrease(uint256 amount) private view returns (bool) { return gTokens(false).totalAssets().mul(utilisationRatioLimitPwrd).div(PERCENTAGE_DECIMAL_FACTOR) >= amount.add(gTokens(true).totalAssets()); } function validGTokenDecrease(uint256 amount) public view override returns (bool) { return gTokens(false).totalAssets().sub(amount).mul(utilisationRatioLimitGvt).div(PERCENTAGE_DECIMAL_FACTOR) >= gTokens(true).totalAssets(); } function setUtilisationRatioLimitPwrd(uint256 _utilisationRatioLimitPwrd) external onlyOwner { utilisationRatioLimitPwrd = _utilisationRatioLimitPwrd; emit LogNewUtilLimit(true, _utilisationRatioLimitPwrd); } function setUtilisationRatioLimitGvt(uint256 _utilisationRatioLimitGvt) external onlyOwner { utilisationRatioLimitGvt = _utilisationRatioLimitGvt; emit LogNewUtilLimit(false, _utilisationRatioLimitGvt); } function getStrategiesTargetRatio() external view override returns (uint256[] memory) { uint256 utilRatio = IPnL(pnl).utilisationRatio(); return IInsurance(insurance).getStrategiesTargetRatio(utilRatio); } } interface IDepositHandler { function depositGvt( uint256[3] calldata inAmounts, uint256 minAmount, address _referral ) external; function depositPwrd( uint256[3] calldata inAmounts, uint256 minAmount, address _referral ) external; } contract DepositHandler is Controllable, FixedStablecoins, FixedVaults, IDepositHandler { IController public ctrl; ILifeGuard public lg; IBuoy public buoy; IInsurance public insurance; mapping(uint256 => bool) public feeToken; using SafeERC20 for IERC20; using SafeMath for uint256; event LogNewFeeToken(address indexed token, uint256 index); event LogNewDependencies(address controller, address lifeguard, address buoy, address insurance); event LogNewDeposit( address indexed user