CurrentAssetsUsd.add(sysState.curveCurrentAssetsUsd); stableState.curveTargetDeltaUsd = curveCurrentAssetsUsd > stableState.curveTargetUsd ? curveCurrentAssetsUsd.sub(stableState.curveTargetUsd) : 0; } else { amountToRebalance = sysState .totalCurrentAssetsUsd .sub(sysState.curveCurrentAssetsUsd) .sub(sysState.lifeguardCurrentAssetsUsd) .add(lg.availableUsd()); } uint256 swapOutTotalUsd = 0; for (uint256 i = 0; i < N_COINS; i++) { uint256 vaultTargetUsd = amountToRebalance.mul(sysState.stablePercents[i]).div(PERCENTAGE_DECIMAL_FACTOR); uint256 vaultTargetAssets; if (!onlySwapOut) { vaultTargetAssets = vaultTargetUsd == 0 ? 0 : buoy.singleStableFromUsd(vaultTargetUsd, int128(i)); stableState.vaultsTargetUsd[i] = vaultTargetUsd; } if (sysState.vaultCurrentAssetsUsd[i] > vaultTargetUsd) { if (!onlySwapOut) { stableState.swapInAmounts[i] = sysState.vaultCurrentAssets[i].sub(vaultTargetAssets); stableState.swapInAmountsUsd[i] = sysState.vaultCurrentAssetsUsd[i].sub(vaultTargetUsd); if (invalidDelta(swapThreshold, stableState.swapInAmountsUsd[i])) { stableState.swapInAmounts[i] = 0; stableState.swapInAmountsUsd[i] = 0; } else { stableState.swapInTotalAmountUsd = stableState.swapInTotalAmountUsd.add( stableState.swapInAmountsUsd[i] ); } } } else { stableState.swapOutPercents[i] = vaultTargetUsd.sub(sysState.vaultCurrentAssetsUsd[i]); if (invalidDelta(swapThreshold, stableState.swapOutPercents[i])) { stableState.swapOutPercents[i] = 0; } else { swapOutTotalUsd = swapOutTotalUsd.add(stableState.swapOutPercents[i]); } } } uint256 percent = PERCENTAGE_DECIMAL_FACTOR; for (uint256 i = 0; i < N_COINS - 1; i++) { if (stableState.swapOutPercents[i] > 0) { stableState.swapOutPercents[i] = stableState.swapOutPercents[i].mul(PERCENTAGE_DECIMAL_FACTOR).div( swapOutTotalUsd ); percent = percent.sub(stableState.swapOutPercents[i]); } } stableState.swapOutPercents[N_COINS - 1] = percent; } function calcStrategyPercent(uint256 utilisationRatio) public pure override returns (uint256[] memo