lts, uint256 withdrawUsd ) external view returns (uint256[3] memory); } contract Exposure is Constants, Controllable, Whitelist, IExposure { using SafeMath for uint256; using SafeERC20 for IERC20; uint256 public protocolCount; uint256 public makerUSDCExposure; event LogNewProtocolCount(uint256 count); event LogNewMakerExposure(uint256 exposure); function setProtocolCount(uint256 _protocolCount) external onlyOwner { protocolCount = _protocolCount; emit LogNewProtocolCount(_protocolCount); } function setMakerUSDCExposure(uint256 _makerUSDCExposure) external onlyOwner { makerUSDCExposure = _makerUSDCExposure; emit LogNewMakerExposure(_makerUSDCExposure); } function getExactRiskExposure(SystemState calldata sysState) external view override returns (ExposureState memory expState) { expState = _calcRiskExposure(sysState, false); ILifeGuard lifeguard = ILifeGuard(_controller().lifeGuard()); IBuoy buoy = IBuoy(_controller().buoy()); for (uint256 i = 0; i < N_COINS; i++) { uint256 assets = lifeguard.assets(i); uint256 assetsUsd = buoy.singleStableToUsd(assets, i); expState.stablecoinExposure[i] = expState.stablecoinExposure[i].add( assetsUsd.mul(PERCENTAGE_DECIMAL_FACTOR).div(sysState.totalCurrentAssetsUsd) ); } } function calcRiskExposure(SystemState calldata sysState) external view override returns (ExposureState memory expState) { expState = _calcRiskExposure(sysState, true); (expState.stablecoinExposed, expState.protocolExposed) = isExposed( sysState.rebalanceThreshold, expState.stablecoinExposure, expState.protocolExposure, expState.curveExposure ); } function getUnifiedAssets(address[N_COINS] calldata vaults) public view override returns (uint256 unifiedTotalAssets, uint256[N_COINS] memory unifiedAssets) { for (uint256 i = 0; i < N_COINS; i++) { uint256 assets = IVault(vaults[i]).totalAssets(); unifiedAssets[i] = assets.mul(DEFAULT_DECIMALS_FACTOR).div( uint256(10)**IERC20Detailed(IVault(vaults[i]).token()).decimals() ); unifiedTotalAssets = unifiedTotalAssets.add(unifiedAssets[i]); } } function calcRoughDelta( uint256[N_COINS] calldata targets, address[N_COINS] calldata vaults, uint256 withdrawUsd ) external view override returns (uint256[N_COINS] memory delta) { (uint256 totalAssets, uint256[N_COINS] memory vaultTotalAssets) = getUnifiedAssets(vaults); require(totalAssets > withdrawUsd, "totalAssets < withdrawalUsd"); totalAssets = totalAssets.sub(withdrawUsd); uint256 totalDelta; for (uint256 i; i < N_COINS; i++) { uint256 target = totalAssets.mul(targets[i]).div(PERCENTAGE_DECIMAL_FACTOR); if (vaultTotalAssets[i] > target) { delta[i] = vaultTotalAssets[i].sub(target); totalDelta = totalDelta.add(delta[i]); } } uint256 percent = PERCENTAGE_DECIMAL_FACTOR; for (uint256 i; i < N_COINS - 1; i++) { if (delta[i] > 0) { delta[i] = delta[i].mul(PERCENTAGE_DECIMAL_FACTOR).div(totalDelta); percent = percent.sub(delta[i]); } } delta[N_COINS - 1] = percent; return delta; } function sortVaultsByDelta( bool bigFirst, uint256 unifiedTotalAssets, uint256[N_COINS] calldata unifiedAssets, uint256[N_COINS] calldata targetPercents ) external pure override returns (uint256[N_COINS] memory vaultIndexes) { uint256 maxIndex; uint256 minIndex; int256 maxDelta; int256 minDelta; for (uint256 i = 0; i < N_COINS; i++) { int256 delta = int256( unifiedAssets[i] - unifiedTotalAssets.mul(targetPercents[i]).div(PERCENTAGE_DECIMAL_FACTOR) ); if (delta > maxDelta) { maxDelta = delta; maxIndex = i; } else if (delta < minDelta) { minDelta = delta; minIndex = i; } } if (bigFirst) { vaultIndexes[0] = maxIndex; vaultIndexes[2] = minIndex; } else { vaultIndexes[0] = minIndex; vaultIndexes[2] = maxIndex; } vaultIndexes[1] = N_COINS - maxIndex - minIndex; } function calculatePercentOfSystem( address vault, uint256 index, uint256 vaultAssetsPercent, uint256 vaultAssets ) private view returns (uint256 percentOfSystem) { if (vaultAssets == 0) return 0; uint256 strategyAssetsPercent = IVault(vault).getStrategyAssets(index).mul(PERCENTAGE_DECIMAL_FACTOR).div( vaultAssets );