function distributeStrategyGainLoss(uint256 gain, uint256 loss) external override {
    uint256 index = vaultIndexes[msg.sender];
    require(index > 0 || index <= N_COINS + 1, "!VaultAdaptor");
    IPnL ipnl = IPnL(pnl);
    IBuoy ibuoy = IBuoy(buoy);
    uint256 gainUsd;
    uint256 lossUsd;
    index = index - 1;
    if (index < N_COINS) {
        if (gain > 0) {
            gainUsd = ibuoy.singleStableToUsd(gain, index);
        } else if (loss > 0) {
            lossUsd = ibuoy.singleStableToUsd(loss, index);
        }
    } else {
        if (gain > 0) {
            gainUsd = ibuoy.lpToUsd(gain);
        } else if (loss > 0) {
            lossUsd = ibuoy.lpToUsd(loss);
        }
    }
    ipnl.distributeStrategyGainLoss(gainUsd, lossUsd, reward);
    if (ibuoy.updateRatios()) {
        ipnl.distributePriceChange(_totalAssets());
    }
}
```
Vulnerability: Broken access control due to incorrect require condition. The condition `index > 0 || index <= N_COINS + 1` is always true for any index. Thus anyone can call this function. They can pass arbitrary `gain` or `loss`, which is converted and passed to PnL, manipulating `lastGvtAssets` and `lastPwrdAssets`. This inflates or deflates GToken price. Combined with the ability to make `ibuoy.updateRatios()` return false (e.g., via flash loan manipulating Curve pool), the `distributePriceChange` correction is skipped, allowing the attacker to withdraw more assets than they should.

